package com.salespunch360.mobile.ui.account.project
import androidx.compose.foundation.clickable;import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.material.icons.Icons;import androidx.compose.material.icons.filled.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.text.font.FontWeight;import androidx.compose.ui.unit.dp;import androidx.lifecycle.compose.collectAsStateWithLifecycle;import androidx.lifecycle.viewmodel.compose.viewModel;import com.salespunch360.mobile.*;import com.salespunch360.mobile.account.*;import kotlinx.serialization.json.*
@Composable fun ProjectScreen(padding:PaddingValues,vm:AccountProjectViewModel=viewModel()){val s=vm.state.collectAsStateWithLifecycle().value;Column(Modifier.fillMaxSize().padding(padding).padding(16.dp)){Row{OutlinedTextField(s.query,vm::search,label={Text("Search projects")},modifier=Modifier.weight(1f));IconButton(vm::load){Icon(Icons.Default.Refresh,"Refresh")};FilledIconButton(vm::create){Icon(Icons.Default.Add,"New project")}};LazyRow{items(listOf<String?>(null,"PLANNING","ACTIVE","ON_HOLD","COMPLETED","CLOSED","CANCELLED")){v->FilterChip(s.status==v,{vm.filter(v)},{Text(v?.replace('_',' ')?:"All")})}};if(s.loading)LinearProgressIndicator(Modifier.fillMaxWidth());s.error?.let{Text(it,color=MaterialTheme.colorScheme.error)};LazyColumn{items(s.rows,key={it.str("id")}){x->ListItem(headlineContent={Text("${x.str("projectNumber")} · ${x.str("name")}",fontWeight=FontWeight.Bold)},supportingContent={Text("${x["customer"]?.jsonObject?.str("name")} · ${x["branch"]?.jsonObject?.str("name")}")},trailingContent={Text(x.str("status"))},modifier=Modifier.clickable{vm.open(x.str("id"))})}}};s.editing?.let{ProjectEditor(it,s.options,vm::close,vm::save)};s.detail?.let{ProjectDetail(it,s.costing,vm::close,vm::edit,vm::action,vm::editBudget)};if(s.budgetEditing&&s.detail!=null)BudgetDialog(s.detail!!,{vm.editBudget(false)},vm::saveBudget)}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun ProjectEditor(x:JsonObject,o:JsonObject,close:()->Unit,save:(JsonObject)->Unit){val edit=x.containsKey("id");var name by remember{mutableStateOf(x.str("name"))};var branch by remember{mutableStateOf(x.str("branchId"))};var customer by remember{mutableStateOf(x.str("customerId"))};var manager by remember{mutableStateOf(x.str("projectManagerId"))};var value by remember{mutableStateOf(x.str("projectValue").ifBlank{"0"})};var start by remember{mutableStateOf(x.str("startDate").take(10))};var end by remember{mutableStateOf(x.str("targetEndDate").take(10))};var status by remember{mutableStateOf(x.str("status").ifBlank{"PLANNING"})};AlertDialog(onDismissRequest=close,title={Text(if(edit)"Edit project" else "New project")},text={LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){item{OutlinedTextField(name,{name=it},label={Text("Project name")})};if(!edit){item{Pick("Branch",branch,o.array("branches")){branch=it}};item{Pick("Customer",customer,o.array("customers").filter{it.jsonObject.str("branchId")==branch}){customer=it}}};item{Pick("Project manager",manager,o.array("managers")){manager=it}};item{OutlinedTextField(value,{value=it},label={Text("Project value")})};item{OutlinedTextField(start,{start=it},label={Text("Start date")})};item{OutlinedTextField(end,{end=it},label={Text("Target end date")})};if(edit)item{PickText("Status",status,listOf("PLANNING","ACTIVE","ON_HOLD","COMPLETED","CANCELLED")){status=it}}}},confirmButton={Button(enabled=name.isNotBlank()&&(edit||branch.isNotBlank()&&customer.isNotBlank()),onClick={save(buildJsonObject{if(edit){put("projectId",x.str("id"));put("status",status)}else{put("branchId",branch);put("customerId",customer)};put("name",name);manager.takeIf{it.isNotBlank()}?.let{put("projectManagerId",it)};start.takeIf{it.isNotBlank()}?.let{put("startDate",it)};end.takeIf{it.isNotBlank()}?.let{put("targetEndDate",it)};put("projectValue",value)})}){Text("Save")}},dismissButton={TextButton(close){Text("Cancel")}})}
@Composable private fun ProjectDetail(x:JsonObject,c:JsonObject?,close:()->Unit,edit:()->Unit,action:(String,String)->Unit,budget:()->Unit){AlertDialog(onDismissRequest=close,title={Text(x.str("projectNumber"))},text={LazyColumn{item{Text(x.str("name"),style=MaterialTheme.typography.titleLarge)};item{Text("${x["customer"]?.jsonObject?.str("name")} · ${x["branch"]?.jsonObject?.str("name")}")};item{Text("Status ${x.str("status")} · Value ₹${x.str("projectValue")}")};item{Text("Customer received ₹${x.str("customerPayments")} · Vendor paid ₹${x.str("vendorPayments")}")};item{Text("Open tasks ${x.str("openTasks")}")};x.str("sourceQuotationId").takeIf{it.isNotBlank()}?.let{q->item{Text("Created from accepted quotation · $q")}};c?.get("metrics")?.jsonObject?.let{m->item{Text("Authoritative costing",style=MaterialTheme.typography.titleMedium)};listOf("estimatedCost","actualCost","committedCost","revenue","profit","actualMarginPercent").forEach{k->item{ListItem(headlineContent={Text(k.replace(Regex("([A-Z])")," $1"))},trailingContent={Text(m.str(k))})}}};c?.array("packages")?.let{packages->item{Text("Package profitability",style=MaterialTheme.typography.titleMedium)};items(packages){p->val v=p.jsonObject;ListItem(headlineContent={Text(v.str("name"))},supportingContent={Text("Revenue ${v.str("actualRevenue")} · Cost ${v.str("actualCost")}")},trailingContent={Text("Profit ${v.str("profit")}")})}};item{Text("Related documents",style=MaterialTheme.typography.titleMedium)};items(x.array("commercialDocuments")){d->Text("${d.jsonObject.str("documentNumber")} · ${d.jsonObject.str("type")} · ${d.jsonObject.str("status")}")}}},confirmButton={Row{Button(edit){Text("Edit")};OutlinedButton(budget){Text("Budget")};if(x.str("status") !in listOf("CLOSED","CANCELLED"))OutlinedButton({action(x.str("id"),"CLOSE")}){Text("Close project")};if(x.str("status")=="CLOSED")OutlinedButton({action(x.str("id"),"REOPEN")}){Text("Reopen")}}},dismissButton={TextButton(close){Text("Close")}})}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun Pick(label:String,value:String,values:List<JsonElement>,set:(String)->Unit){var open by remember{mutableStateOf(false)};val selected=values.map{it.jsonObject}.firstOrNull{it.str("id")==value};ExposedDropdownMenuBox(open,{open=it}){OutlinedTextField(selected?.str("name").orEmpty(),{},readOnly=true,label={Text(label)},modifier=Modifier.menuAnchor());ExposedDropdownMenu(open,{open=false}){values.forEach{e->val x=e.jsonObject;DropdownMenuItem({Text(x.str("name"))},{set(x.str("id"));open=false})}}}}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun PickText(label:String,value:String,values:List<String>,set:(String)->Unit){var open by remember{mutableStateOf(false)};ExposedDropdownMenuBox(open,{open=it}){OutlinedTextField(value,{},readOnly=true,label={Text(label)},modifier=Modifier.menuAnchor());ExposedDropdownMenu(open,{open=false}){values.forEach{v->DropdownMenuItem({Text(v)},{set(v);open=false})}}}}

@Composable private fun BudgetDialog(project:JsonObject,close:()->Unit,save:(String,String)->Unit){var amount by remember{mutableStateOf(project.str("budgetTotal"))};AlertDialog(onDismissRequest=close,title={Text("Project budget")},text={OutlinedTextField(amount,{amount=it},label={Text("Budget amount")})},confirmButton={Button(enabled=amount.isNotBlank(),onClick={save(project.str("id"),amount)}){Text("Save authoritative budget")}},dismissButton={TextButton(close){Text("Cancel")}})}
